import{d as e,i as t,n}from"./index-C8BGTi7B.js";var r=[`Arvane was created to redefine the cafe experience by removing the noise, the excess, and the ordinary.`,`Modern cafes have become louder, faster, and increasingly transactional. Spaces designed for convenience rather than presence. Coffee reduced to routine. Environments filled, but rarely considered.`,`Arvane was built in response to that.`,`From the beginning, the goal was not to follow trends, but to establish a different standard: one rooted in clarity, restraint, and purpose. A place where every element serves a role, and nothing exists without reason.`,`This philosophy shapes everything.`,`The coffee is not rushed. Each cup is prepared with measured precision, with timing, temperature, and balance treated as essential variables, not afterthoughts. What is served is deliberate, consistent, and repeatable.`,`The space follows the same principle. Lighting is softened to create focus, not distraction. Materials are chosen for their presence, not excess. The layout is structured to feel open, yet contained, allowing movement without noise.`,`Arvane does not aim to offer everything. It aims to offer what matters: refined, reduced, and executed at a higher level. A menu that is curated rather than expanded. An environment that is designed rather than filled.`,`Because a better experience is not created by adding more, but by removing what does not belong.`,`At its core, Arvane is built on the belief that small details, when treated with care, transform the entire experience.`,`Arvane exists to elevate the everyday.`],i=[`Our philosophy begins with restraint. We believe a cafe should not overwhelm the guest. It should give them room to arrive, settle, and enjoy what is in front of them.`,`Craftsmanship is treated as a daily practice, not a slogan. Beans are selected with care, drinks are prepared with consistency, and each recipe is designed around balance rather than excess.`,`Quality also means honesty. We favor real ingredients, clean flavors, and a focused menu that can be prepared well every time.`,`The atmosphere matters as much as the cup. Light, sound, seating, and service all work together to create a place that feels calm, useful, and considered.`],a=[`Our commitment is to keep Arvane thoughtful as it grows. Every detail, from sourcing to service, should support the same promise: a refined experience that still feels warm and human.`,`We are committed to consistency, sustainability, and community. That means responsible choices where they matter, dependable quality in what we serve, and a space where guests feel welcome without the experience feeling ordinary.`,`Arvane is built around small decisions made with care, because those decisions shape how the whole visit feels.`],o=`/assets/about-hero-CZqz-3PG.jpg`,s={panel:`_panel_18ag3_1`,eyebrow:`_eyebrow_18ag3_6`,storyBody:`_storyBody_18ag3_20`,textBody:`_textBody_18ag3_21`},c=e(),l=[{eyebrow:`Our Story`,title:`Built For Presence`,paragraphs:r,variant:`story`},{eyebrow:`Our Philosophy`,title:`Measured, Calm, Intentional`,paragraphs:i},{eyebrow:`Our Commitment`,title:`A Promise In Practice`,paragraphs:a}];function u(){return(0,c.jsxs)(c.Fragment,{children:[(0,c.jsx)(t,{title:`About Arvane`,subtitle:`Crafted with passion, served with care`,image:o}),l.map(({eyebrow:e,title:t,paragraphs:r,variant:i})=>(0,c.jsx)(n,{children:(0,c.jsxs)(`article`,{className:s.panel,children:[(0,c.jsx)(`span`,{className:s.eyebrow,children:e}),(0,c.jsx)(`h2`,{children:t}),(0,c.jsx)(`div`,{className:i===`story`?s.storyBody:s.textBody,children:r.map(e=>(0,c.jsx)(`p`,{children:e},e))})]})},e))]})}export{u as default};